namespace Silvergun.PackageAnalysis.NuGet.Squats;

/// <summary>
/// A record of a single mutation generated by an <see cref="IMutator"/>: the <paramref name="Mutated"/>
/// candidate name, the <paramref name="Original"/> input, a human-readable <paramref name="Reason"/>,
/// and the <paramref name="Mutator"/> kind that produced it.
/// </summary>
public sealed record Mutation(string Mutated, string Original, string Reason, MutatorType Mutator);
